/* ---- classify the quantity currently shown in the field ---- */
function classifyDisplayed(){
  var raw = qty.value.trim();
  if (raw === "") return { state:"empty" };
  var n = Number(raw);
  if (!Number.isFinite(n) || !Number.isInteger(n)) return { state:"fractional" };
  if (n < QMIN) return { state:"nonpositive" };
  return { state:"valid", value:n };
}

function invalidMessage(state){
  if (state === "empty") return "Enter a quantity — whole cups from 1 up to " + cap() + ".";
  if (state === "nonpositive") return "Quantity must be at least 1 — enter 1 or more.";
  return "Whole cups only — enter a number without decimals, such as 1, 2, 3 or 4.";
}

/* ---- quantity validation: empty / small / fractional / excessive ---- */
function readQty(){
  var d = classifyDisplayed();
  if (d.state !== "valid") return { ok:false, msg:invalidMessage(d.state) };
  var c = cap();
  if (d.value > c) {
    if (c < QMAX) {
      return { ok:false, msg:"Only " + c + " " + currentGlaze + " cups in stock — enter " + c + " or fewer." };
    }
    return { ok:false, msg:"Maximum " + QMAX + " per order — enter 4 or fewer." };
  }
  return { ok:true, value:d.value };
}

