input.newString:
/* ---- glaze switch: judge the displayed quantity, not the last accepted one ---- */
radios.forEach(function(r){
  r.addEventListener("change", function(e){
    if (!e.target.checked) return;
    currentGlaze = e.target.value;
    clearSuccess();
    clearPanelAlert();
    updateGlazeUi();
    var d = classifyDisplayed();
    if (d.state !== "valid") {
      // keep the invalid state visible with fresh, actionable feedback
      qtyError.textContent = invalidMessage(d.state);
      qty.setAttribute("aria-invalid", "true");
      renderStaleTotals();
      setCostStale(true);
      return;
    }
    var c = cap();
    if (d.value > c) {
      lastValidQty = c;
      qty.value = String(c);
      renderTotals(c);
      setCostStale(false);
      clearQtyError();
      panelStatus.textContent =
        "Quantity reduced to " + c + " — " + currentGlaze + " has " + c + " in stock.";
    } else {
      lastValidQty = d.value;
      renderTotals(d.value);
      setCostStale(false);
      clearQtyError();
    }
  });
});

